// Future Tender · FT29 "The bitcoin machine at the gas station" — HYBRID: Blender renders the 3D world (bg video,
// incl. 110 extra frames after the main timeline = the victim camera for the split screen), Remotion adds captions,
// pills, tags, counters and screen UIs, word-locked and tracked with per-frame anchors exported by the Blender bake.
import React from "react";
import { AbsoluteFill, OffthreadVideo, Sequence, useCurrentFrame } from "remotion";
import WORDS from "../data/ft29_words.json";
import AN from "../data/ft29_anchors.json";
import { clamp, easeOut } from "../kit/core";
import { cue, vis, Wd, SANS, MONO, FPS, useFonts } from "../kit/std";
import { chunks2, Tag2, StatusPill, CapPill, EndTag, Foot2 } from "../kit/sth";

const W = WORDS as Wd[];
const T = cue(W);
export const FT29_DUR = W[W.length - 1].end + 1.2;
export const FT29_SRC_DEFAULT = "https://d2ol7oe51mr4n9.cloudfront.net/user_38Z8oWSnRHNn2APJObaAQyRFvxH/REPLACE_BG.mp4";
const K = { cyan: "#38d6ff", red: "#ff4d4d", green: "#5dff8f", amber: "#ffb547", ink: "#e9eef5", warm: "#fff3dc" };
const C = {
  scam: T("scam"), online: T("online"), happens: T("It happens"), gas: T("gas"), last: T("Last"), n388: T("$388"), million: T("million"), thisway: T("this way"),
  starts: T("It starts"), call: T("call"), banks: T("bank's"), someone: T("Someone's"), account: T("account"), move: T("Move"), dont: T("don't"),
  keep: T("They keep"), bank: T("bank", 0), then: T("then"), gas2: T("gas", 1), next: T("Next"), glowing: T("glowing"), bitcoin: T("bitcoin"),
  text: T("text"), qr: T("QR"), feed: T("feed"), so: T("So where"), that: T("That"), qr2: T("QR", 1), wallet: T("wallet"),
  second: T("The second"), bill: T("bill"), theirs: T("theirs"), cant: T("can't"), fraud: T("The fraud"), was: T("was the fraud"),
  early: T("In early"), typical: T("typical"), tenk: T("$10,000"), over: T("Over half"), people: T("people"), fifty: T("50"),
  thisyear: T("This year"), three: T("three"), banned: T("banned"), but: T("But"), cop: T("cop"), government: T("government"),
  bitcoin3: T("bitcoin", 1), soif: T("So if"), gas3: T("gas", 2), never: T("never"), yourbank: T("your bank"),
};
const ALT0 = 31.74, ALT1 = 35.38;

/* ---------- anchors ---------- */
type P2 = [number, number] | null;
const A = (AN as any).a as Record<string, P2[]>;
const NTOT = (AN as any).ntot as number; const EX0 = (AN as any).ex0 as number;
const at = (name: string, f: number) => { const p = A[name]?.[Math.max(0, Math.min(NTOT - 1, f))]; return p ? { x: p[0], y: p[1], vis: p[0] > -200 && p[0] < 1280 && p[1] > -200 && p[1] < 2120 } : { x: 0, y: 0, vis: false }; };
const quad = (name: string, f: number): number[][] | null => {
  const q: number[][] = [];
  for (let i = 0; i < 4; i++) { const p = A[name + i]?.[Math.max(0, Math.min(NTOT - 1, f))]; if (!p) return null; q.push(p); }
  return q;
};
const homography = (p: number[][], w: number, h: number) => {
  const [x0, y0] = p[0], [x1, y1] = p[1], [x2, y2] = p[2], [x3, y3] = p[3];
  const dx1 = x1 - x2, dx2 = x3 - x2, dx3 = x0 - x1 + x2 - x3, dy1 = y1 - y2, dy2 = y3 - y2, dy3 = y0 - y1 + y2 - y3;
  let a13 = 0, a23 = 0;
  if (Math.abs(dx3) > 1e-9 || Math.abs(dy3) > 1e-9) { const den = dx1 * dy2 - dx2 * dy1; a13 = (dx3 * dy2 - dx2 * dy3) / den; a23 = (dx1 * dy3 - dx3 * dy1) / den; }
  const a11 = x1 - x0 + a13 * x1, a21 = x3 - x0 + a23 * x3, a31 = x0, a12 = y1 - y0 + a13 * y1, a22 = y3 - y0 + a23 * y3, a32 = y0;
  const m = [a11 / w, a12 / w, 0, a13 / w, a21 / h, a22 / h, 0, a23 / h, 0, 0, 1, 0, a31, a32, 0, 1];
  return `matrix3d(${m.map((v) => v.toFixed(8)).join(",")})`;
};
const area = (q: number[][]) => { let s = 0; for (let i = 0; i < 4; i++) { const a = q[i], b = q[(i + 1) % 4]; s += a[0] * b[1] - b[0] * a[1]; } return Math.abs(s) / 2; };
const OnQuad: React.FC<{ q: number[][] | null; w: number; h: number; o?: number; children: React.ReactNode; minArea?: number; dx?: number }> = ({ q, w, h, o = 1, children, minArea = 500, dx = 0 }) => {
  if (!q || o <= 0 || area(q) < minArea) return null;
  const qq = q.map((p) => [p[0] + dx, p[1]]);
  return <div style={{ position: "absolute", left: 0, top: 0, width: w, height: h, transformOrigin: "0 0", transform: homography(qq, w, h), opacity: o, overflow: "hidden" }}>{children}</div>;
};

/* ---------- screens ---------- */
const QR: React.FC<{ s: number; color?: string }> = ({ s, color = "#111" }) => {
  const n = 21; const cells: React.ReactNode[] = [];
  let seed = 7; const rnd = () => { seed = (seed * 9301 + 49297) % 233280; return seed / 233280; };
  for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) {
    const finder = (x < 7 && y < 7) || (x > 13 && y < 7) || (x < 7 && y > 13);
    let on = rnd() > 0.52;
    if (finder) { const fx = x > 13 ? x - 14 : x, fy = y > 13 ? y - 14 : y; on = fx === 0 || fx === 6 || fy === 0 || fy === 6 || (fx >= 2 && fx <= 4 && fy >= 2 && fy <= 4); }
    if (on) cells.push(<rect key={x + "_" + y} x={x} y={y} width={1.02} height={1.02} fill={color} />);
  }
  return <svg width={s} height={s} viewBox={`-1 -1 ${n + 2} ${n + 2}`} style={{ background: "#fff", borderRadius: s * 0.04 }}>{cells}</svg>;
};
const kioskCash = (t: number) => {
  // dollars inside the machine (each bill = $20)
  const s1 = [0.66, 1.52]; const s5 = [25.62, 26.04, 26.44]; const alt = [32.22, 32.82, 33.42];
  let n = 0; for (const x of s1) if (t >= x) n++;
  if (t >= 20) { n = 4; for (const x of s5) if (t >= x) n++; }
  return n * 20;
};
const KioskUI: React.FC<{ t: number; altT?: number; w: number; h: number }> = ({ t, altT, w, h }) => {
  const tt = altT ?? t;
  const cash = altT !== undefined ? 140 + 20 * [32.22, 32.82, 33.42].filter((x) => altT >= x).length : kioskCash(t);
  const qrStage = tt >= 24.3 && tt < 25.3;
  const sent = altT !== undefined || (tt >= 28.4 && tt < 54);
  const dim = clamp((t - 57.4) / 0.5);
  return (
    <div style={{ width: w, height: h, background: "linear-gradient(180deg,#05202e,#03111b)", color: "#dff6ff", fontFamily: SANS, padding: w * 0.07, boxSizing: "border-box", opacity: 1 - 0.85 * dim, position: "relative" }}>
      <div style={{ fontFamily: MONO, fontSize: w * 0.06, letterSpacing: 3, color: K.cyan }}>CRYPTO KIOSK</div>
      <div style={{ height: 2, background: "#0f4a63", margin: `${w * 0.05}px 0` }} />
      {qrStage ? (
        <>
          <div style={{ fontWeight: 800, fontSize: w * 0.09, lineHeight: 1.1 }}>SCAN WALLET QR</div>
          <div style={{ marginTop: w * 0.06, display: "flex", justifyContent: "center" }}><div style={{ width: w * 0.5, height: w * 0.5, border: `4px dashed ${K.cyan}`, borderRadius: 12 }} /></div>
        </>
      ) : (
        <>
          <div style={{ fontWeight: 700, fontSize: w * 0.075, color: "#8fc9de" }}>{sent ? "SENT TO WALLET" : "INSERT CASH"}</div>
          <div style={{ fontWeight: 800, fontSize: w * 0.24, letterSpacing: -2, marginTop: w * 0.02, color: sent ? K.green : "#fff" }}>${cash}</div>
          <div style={{ fontFamily: MONO, fontSize: w * 0.05, color: "#5f93a8", marginTop: w * 0.03 }}>BILLS ACCEPTED</div>
          {[0, 1, 2].map((i) => <div key={i} style={{ height: w * 0.08, borderRadius: 8, background: "#0a2c3d", marginTop: w * 0.05 }} />)}
        </>
      )}
    </div>
  );
};
const callerName = (t: number) => {
  // letters fall away at "was the fraud" until only FRAUD stays
  const full = "BANK FRAUD TEAM";
  if (t < C.was) return { txt: full, drop: 0 };
  return { txt: full, drop: clamp((t - C.was) / 0.7) };
};
const CallUI: React.FC<{ t: number; w: number; h: number; mode: "ring" | "call" | "qr" }> = ({ t, w, h, mode }) => {
  const cn = callerName(t);
  return (
    <div style={{ width: w, height: h, background: mode === "qr" ? "#0d1117" : "linear-gradient(180deg,#14324a,#0b1724)", color: "#fff", fontFamily: SANS, padding: w * 0.08, boxSizing: "border-box", position: "relative", overflow: "hidden" }}>
      {mode === "qr" ? (
        <>
          <div style={{ fontFamily: MONO, fontSize: w * 0.06, color: "#9aa7b8" }}>MESSAGES</div>
          <div style={{ marginTop: w * 0.1, background: "#2a3443", borderRadius: w * 0.06, padding: w * 0.06, width: w * 0.78 }}>
            <div style={{ fontSize: w * 0.075, fontWeight: 700, marginBottom: w * 0.04 }}>Scan this at the machine</div>
            <QR s={w * 0.62} />
          </div>
        </>
      ) : (
        <>
          <div style={{ display: "flex", justifyContent: "center", marginTop: w * 0.18 }}>
            <svg width={w * 0.34} height={w * 0.4} viewBox="0 0 34 40"><path d="M17 2 L31 8 V19 C31 29 24 35 17 38 C10 35 3 29 3 19 V8 Z" fill="#2f7de1" stroke="#cfe3ff" strokeWidth="2" /><path d="M11 20 l4 4 l8 -9" stroke="#fff" strokeWidth="3" fill="none" /></svg>
          </div>
          <div style={{ textAlign: "center", marginTop: w * 0.08, fontWeight: 800, fontSize: w * 0.1, lineHeight: 1.15 }}>
            {cn.txt.split("").map((ch, i) => {
              const keep = i >= 5 && i <= 9;
              const d = keep ? 0 : clamp(cn.drop * 1.6 - (i % 5) * 0.12);
              return <span key={i} style={{ display: "inline-block", transform: `translateY(${d * h * 0.9}px) rotate(${d * (i % 2 ? 40 : -35)}deg)`, opacity: 1 - d * 0.6, color: keep && cn.drop > 0 ? K.red : "#fff" }}>{ch === " " ? " " : ch}</span>;
            })}
          </div>
          <div style={{ textAlign: "center", fontFamily: MONO, fontSize: w * 0.06, color: "#9fb4cc", marginTop: w * 0.05 }}>{mode === "ring" ? "INCOMING CALL" : "ON CALL 04:12"}</div>
          {mode === "ring" && <div style={{ position: "absolute", bottom: w * 0.18, left: 0, right: 0, display: "flex", justifyContent: "space-around" }}>
            <div style={{ width: w * 0.2, height: w * 0.2, borderRadius: "50%", background: "#e5484d" }} /><div style={{ width: w * 0.2, height: w * 0.2, borderRadius: "50%", background: "#30a46c" }} /></div>}
        </>
      )}
    </div>
  );
};

/** readable floating copy of a phone screen with a leader line to the 3D phone */
const Float: React.FC<{ t: number; t0: number; t1: number; anchor: { x: number; y: number; vis: boolean }; x: number; y: number; w: number; h: number; children: React.ReactNode; shake?: number }> = ({ t, t0, t1, anchor, x, y, w, h, children, shake = 0 }) => {
  const o = vis(t, t0, t1, 0.18); if (o <= 0) return null;
  const g = easeOut(clamp((t - t0) / 0.3)); const sx = shake * Math.sin(t * 70) * 6;
  return (
    <>
      {anchor.vis && <svg width="1080" height="1920" style={{ position: "absolute", left: 0, top: 0, opacity: o * 0.8 }}>
        <circle cx={anchor.x} cy={anchor.y} r="6" fill={K.ink} />
        <line x1={anchor.x} y1={anchor.y} x2={x + w / 2} y2={y + h} stroke={K.ink} strokeWidth="1.6" strokeDasharray="5 6" />
      </svg>}
      <div style={{ position: "absolute", left: x + sx, top: y, width: w, height: h, borderRadius: 34, overflow: "hidden", opacity: o, transform: `scale(${0.85 + 0.15 * g})`, transformOrigin: "50% 100%", boxShadow: "0 18px 50px rgba(0,0,0,0.6)", border: "3px solid rgba(220,230,245,0.25)" }}>{children}</div>
