};
const Counter: React.FC<{ t: number; t0: number; t1: number; to: number; prefix?: string; suffix?: string; x: number; y: number; color: string; size?: number; dur?: number; sub?: string; subT?: number }> = ({ t, t0, t1, to, prefix = "", suffix = "", x, y, color, size = 150, dur = 0.7, sub, subT = 0 }) => {
  const o = vis(t, t0 - 0.05, t1, 0.15); if (o <= 0) return null;
  const k = easeOut(clamp((t - t0) / dur)); const v = Math.round(to * k);
  const punch = 1 + 0.08 * Math.sin(clamp((t - t0 - dur) / 0.2) * Math.PI);
  const so = sub ? vis(t, subT, t1, 0.1) : 0; const ss = 1 + 0.5 * (1 - easeOut(clamp((t - subT) / 0.18)));
  return (
    <div style={{ position: "absolute", left: x - 400, width: 800, top: y, textAlign: "center", opacity: o }}>
      <div style={{ fontFamily: SANS, fontWeight: 800, fontSize: size, letterSpacing: -4, color, transform: `scale(${punch})`, textShadow: "0 8px 40px rgba(0,0,0,0.75)" }}>{prefix}{v.toLocaleString("en-US")}{suffix}</div>
      {sub && so > 0 && <div style={{ display: "inline-block", marginTop: -10, padding: "6px 22px", borderRadius: 12, background: color, color: "#10161f", fontFamily: SANS, fontWeight: 800, fontSize: size * 0.4, letterSpacing: 2, opacity: so, transform: `scale(${ss})` }}>{sub}</div>}
    </div>
  );
};
const Laptop: React.FC<{ t: number }> = ({ t }) => {
  const o = vis(t, C.online - 0.1, 2.72, 0.15); if (o <= 0) return null;
  const g = easeOut(clamp((t - C.online + 0.1) / 0.25)); const fold = clamp((t - 2.2) / 0.4); const x = clamp((t - 1.82) / 0.15);
  return (
    <div style={{ position: "absolute", left: 70, top: 380, width: 340, height: 300, opacity: o, transform: `scale(${0.6 + 0.4 * g}) rotate(${-6 + 4 * Math.sin(t * 9) * (t > 2.0 && t < 2.3 ? 1 : 0)}deg)`, transformOrigin: "50% 100%" }}>
      <div style={{ position: "absolute", left: 30, top: 0, width: 280, height: 180, borderRadius: 14, background: "#1d2633", border: "6px solid #c9d2de", transformOrigin: "50% 100%", transform: `perspective(600px) rotateX(${-88 * fold}deg)` }}>
        <svg width="280" height="170" viewBox="0 0 280 170"><rect x="115" y="70" width="50" height="40" rx="6" fill="#c9d2de" /><path d="M125 70 v-12 a15 15 0 0 1 30 0 v12" stroke="#c9d2de" strokeWidth="7" fill="none" /></svg>
      </div>
