      {x > 0 && <svg width="340" height="260" style={{ position: "absolute", left: 0, top: -20, opacity: x }}><path d="M80 40 L260 220 M260 40 L80 220" stroke="#8a93a1" strokeWidth={22 * x} strokeLinecap="round" /></svg>}
    </div>
