};
const Sweat: React.FC<{ t: number; at: { x: number; y: number; vis: boolean } }> = ({ t, at }) => {
  const k = clamp((t - C.someone) / 0.9); if (k <= 0 || k >= 1 || !at.vis) return null;
  return <svg width="60" height="80" style={{ position: "absolute", left: at.x + 40 + 20 * k, top: at.y - 40 + 120 * k * k, opacity: 1 - k * 0.6 }}><path d="M30 5 C 45 35 52 50 52 60 a22 22 0 0 1 -44 0 C 8 50 15 35 30 5 Z" fill="#7fd3ff" stroke="#e8f7ff" strokeWidth="3" /></svg>;
};
const BalanceBar: React.FC<{ t: number }> = ({ t }) => {
  const o = vis(t, C.someone, C.move - 0.1, 0.2); if (o <= 0) return null;
  const k = clamp((t - C.someone - 0.2) / 1.0); const red = t >= C.account && t < C.account + 0.5 && Math.floor((t - C.account) * 10) % 2 === 0;
  return (
