      <div style={{ marginTop: 14, height: 34, borderRadius: 10, background: "#1f2836", overflow: "hidden" }}><div style={{ height: "100%", width: `${100 - 88 * k}%`, background: red ? K.red : "#3fb7ff" }} /></div>
      <div style={{ marginTop: 10, fontFamily: SANS, fontWeight: 800, fontSize: 40, color: red ? K.red : "#fff" }}>${Math.round(12480 - 10980 * k).toLocaleString("en-US")}</div>
