      <div style={{ position: "absolute", left: 0, right: 0, top: 410, textAlign: "center", fontFamily: MONO, fontSize: 26, letterSpacing: 4, color: "#9aa7b8" }}>CRYPTO KIOSKS · 2026</div>
      {TILES.map(([s, gx, gy], i) => {
