        return <div key={s} style={{ position: "absolute", left: 90 + i * 310, top: 1110, width: 280, textAlign: "center", opacity: k, fontFamily: SANS, fontWeight: 800, fontSize: 34, color: "#fff" }}>{name}<div style={{ fontFamily: MONO, fontSize: 20, color: t >= C.banned + i * 0.12 ? K.red : "#9aa7b8", letterSpacing: 2 }}>{t >= C.banned + i * 0.12 ? "MACHINES BANNED" : "2026"}</div></div>;
      })}
    </div>
  );
};
const SlashRing: React.FC<{ t: number; at: { x: number; y: number; vis: boolean } }> = ({ t, at }) => {
