    <line x1={at.x - r * 0.7} y1={at.y + r * 0.7} x2={at.x - r * 0.7 + 1.4 * r * clamp((k - 0.5) * 2)} y2={at.y + r * 0.7 - 1.4 * r * clamp((k - 0.5) * 2)} stroke={K.red} strokeWidth="20" strokeLinecap="round" />
  </svg>;
};

const CH = chunks2(W, 4);
const STATUS: [number, string, string][] = [
  [0, "CASH IN · CRYPTO KIOSK", K.cyan], [C.happens, "GAS STATION · 2 AM", K.amber], [C.n388, "$388M REPORTED · 2025", K.red],
  [C.starts, "INCOMING CALL", K.ink], [C.someone, "FAKE ALARM", K.red], [C.move, "KEEP YOU ON THE LINE", K.amber],
